export class Stream {
    produce;
    constructor(produce) {
        this.produce = produce;
    }
    subscribe(o) {
        const full = typeof o === "function"
            ? { next: o, complete: () => { } }
            : { next: (v) => o?.next?.(v), complete: () => o?.complete?.() };
        this.produce(full);
    }
}
function isSched(value) {
    return !!value && typeof value.now === "function";
}
export function of(...args) {
    const items = (isSched(args[args.length - 1]) ? args.slice(0, -1) : args);
    return new Stream((o) => {
        for (const v of items)
            o.next(v);
        o.complete();
    });
}
export function defer(factory) {
    return new Stream((o) => {
        const made = factory();
        if (made instanceof Stream)
            made.subscribe(o);
        else if (Array.isArray(made)) {
            for (const v of made)
                o.next(v);
            o.complete();
        }
        else {
            made.then((v) => {
                o.next(v);
                o.complete();
            });
        }
    });
}
export function lastValueFrom(source) {
    return new Promise((resolve, reject) => {
        let has = false;
        let value;
        source.subscribe({
            next: (v) => {
                has = true;
                value = v;
            },
            complete: () => (has ? resolve(value) : reject(new Error("no elements"))),
        });
    });
}
